import React, { Component } from 'react';
import { NavLink } from 'react-router-dom';
import MyContext from '../contexts/MyContext';
import '../css/MenuComponent.css';

class Menu extends Component {
  static contextType = MyContext;

  btnLogoutClick = () => {
    this.context.setToken('');
    this.context.setUsername('');
  };

  render() {
    return (
      <div className="admin-navbar">
        <div className="admin-navbar-brand">
          Nhà hàng Văn Lang
        </div>

        <div className="admin-navbar-links">
          <NavLink to="/admin/report" className={({ isActive }) => isActive ? 'admin-nav-item active' : 'admin-nav-item'}>
            Báo cáo
          </NavLink>
          <NavLink to="/admin/category" className={({ isActive }) => isActive ? 'admin-nav-item active' : 'admin-nav-item'}>
            Danh mục
          </NavLink>
          <NavLink to="/admin/product" className={({ isActive }) => isActive ? 'admin-nav-item active' : 'admin-nav-item'}>
            Thực đơn
          </NavLink>
          <NavLink to="/admin/order" className={({ isActive }) => isActive ? 'admin-nav-item active' : 'admin-nav-item'}>
            Đơn hàng
          </NavLink>
          <NavLink to="/admin/customer" className={({ isActive }) => isActive ? 'admin-nav-item active' : 'admin-nav-item'}>
            Khách hàng
          </NavLink>
          <NavLink to="/admin/voucher" className={({ isActive }) => isActive ? 'admin-nav-item active' : 'admin-nav-item'}>
            Mã giảm giá
          </NavLink>
        </div>

        <div className="admin-navbar-user">
          <span>Hi <b>{this.context.username || 'Quản lý'}</b></span>
          <button className="btn-logout" onClick={this.btnLogoutClick}>
            Logout
          </button>
        </div>
      </div>
    );
  }
}

export default Menu;
